package com.ruoyi.ai.agent;

import com.fasterxml.jackson.databind.node.*;
import junit.framework.TestCase;
import static com.ruoyi.ai.agent.AgentJson.*;

public class B7FormulaManifestTest extends TestCase {
    private ObjectNode snapshot(){return (ObjectNode)parse("{\"sheets\":{\"s\":{\"name\":\"Sheet\",\"rowCount\":8,\"columnCount\":5,\"cellData\":{\"0\":{\"0\":{\"v\":2,\"t\":2},\"1\":{\"v\":3,\"t\":2}},\"1\":{\"0\":{\"v\":4,\"t\":2},\"1\":{\"v\":5,\"t\":2}}},\"mergeData\":[]}}}");}
    private ArrayNode scopes(){return (ArrayNode)parse("[{\"sheetId\":\"s\",\"range\":\"C1:C2\"}]");}
    private ObjectNode action(String range,String formula){return (ObjectNode)parse("{\"schemaVersion\":\"2.0\",\"type\":\"setFormula\",\"target\":{\"sheetId\":\"s\",\"range\":\""+range+"\"},\"formula\":\""+formula+"\"}");}
    private void reject(Runnable run){try{run.run();fail("Unsafe formula accepted");}catch(IllegalArgumentException expected){assertNotNull(expected.getMessage());}}
    public void testGateAndArithmeticFill(){assertFalse(WriteManifest.availableActions(true,false).contains("setFormula"));assertTrue(WriteManifest.availableActions(true,false,true).contains("setFormula"));ObjectNode a=action("C1:C2","=A1+B1");reject(()->WriteManifest.classify(arr().add(a),true,false));assertEquals("controlled-values",WriteManifest.classify(arr().add(a),true,false,true));ObjectNode manifest=FormulaManifest.preview(snapshot(),a,scopes());assertEquals("=A1+B1",manifest.path("formulaPatch").path("cells").get(0).path("formula").asText());assertEquals(5,manifest.path("formulaPatch").path("cells").get(0).path("value").asInt());assertEquals("=A2+B2",manifest.path("formulaPatch").path("cells").get(1).path("formula").asText());assertEquals(9,manifest.path("formulaPatch").path("cells").get(1).path("value").asInt());ObjectNode saved=FormulaManifest.apply(snapshot(),manifest);assertEquals("=A2+B2",saved.path("sheets").path("s").path("cellData").path("1").path("2").path("f").asText());}
    public void testSumAndMixedReferences(){ObjectNode sum=FormulaManifest.preview(snapshot(),action("C1","=SUM(A1:B2)"),(ArrayNode)parse("[{\"sheetId\":\"s\",\"range\":\"C1\"}]"));assertEquals(14,sum.path("formulaPatch").path("cells").get(0).path("value").asInt());ObjectNode mixed=FormulaManifest.preview(snapshot(),action("C1:C2","=$A1+B$1"),scopes());assertEquals("=$A2+B$1",mixed.path("formulaPatch").path("cells").get(1).path("formula").asText());assertEquals(7,mixed.path("formulaPatch").path("cells").get(1).path("value").asInt());}
    public void testInvalidDependencyAndScopeReject(){reject(()->FormulaManifest.preview(snapshot(),action("C1:C2","=A1+B1"),(ArrayNode)parse("[{\"sheetId\":\"s\",\"range\":\"C1\"}]")));reject(()->FormulaManifest.preview(snapshot(),action("C1:C2","=A1/0"),scopes()));reject(()->FormulaManifest.preview(snapshot(),action("C1:C2","=A1/ B1"),scopes()));reject(()->FormulaManifest.preview(snapshot(),action("C1:C2","=INDIRECT(A1)"),scopes()));ObjectNode bad=snapshot();((ObjectNode)bad.path("sheets").path("s").path("cellData").path("0").path("0")).put("f","=1+1");reject(()->FormulaManifest.preview(bad,action("C1:C2","=A1+B1"),scopes()));ObjectNode overlap=action("C1:C2","=C1+B1");reject(()->FormulaManifest.preview(snapshot(),overlap,scopes()));}
    public void testTamperAndReadbackReject(){ObjectNode initial=snapshot(),m=FormulaManifest.preview(initial,action("C1:C2","=A1+B1"),scopes());FormulaManifest.validateReceipt(m,m.path("formulaReadback"));reject(()->FormulaManifest.validateReceipt(m,arr().add(obj().put("formula","=1+1"))));ObjectNode forged=m.deepCopy();((ObjectNode)forged.path("formulaPatch").path("cells").get(0)).put("value",99);reject(()->FormulaManifest.apply(initial,forged));assertFalse(initial.path("sheets").path("s").path("cellData").path("0").has("2"));}
    public void testDivideByZeroAndFractionReject(){ObjectNode zero=snapshot();((ObjectNode)zero.path("sheets").path("s").path("cellData").path("0").path("1")).put("v",0);reject(()->FormulaManifest.preview(zero,action("C1:C2","=A1/B1"),scopes()));reject(()->FormulaManifest.preview(snapshot(),action("C1:C2","=B1/A1"),scopes()));}
    public void testSavedCacheIndependentlyRechecked(){ObjectNode m=FormulaManifest.preview(snapshot(),action("C1:C2","=A1+B1"),scopes()),saved=FormulaManifest.apply(snapshot(),m);String call="b7-call";ObjectNode change=obj().put("kind","controlled-formula").put("operationId",call).put("afterHash",hash(saved));change.set("formulaPatch",m.path("formulaPatch"));ObjectNode write=obj().put("transportVersion",2).put("callId",call).put("persistenceStatus","SAVED").put("validation","PASSED").put("loadedRevision",hash(saved)).put("sourceRevision",hash(saved));write.set("executedChange",change);write.set("actions",m.path("actions"));ObjectNode args=obj().put("sheetId","s").put("range","C1:C2").put("kind","matches_formula");args.set("write",write);assertTrue(AgentTools.verify(saved,args).path("passed").asBoolean());ObjectNode altered=saved.deepCopy();((ObjectNode)altered.path("sheets").path("s").path("cellData").path("0").path("2")).put("v",99);String alteredHash=hash(altered);write.put("loadedRevision",alteredHash).put("sourceRevision",alteredHash);change.put("afterHash",alteredHash);reject(()->AgentTools.verify(altered,args));}
}
